Widget originalSelection(bool selected, Widget child, BuildContext context) {
  final reduced = MediaQuery.disableAnimationsOf(context);
  return Semantics(selected: selected, child: AnimatedContainer(
    duration: reduced ? Duration.zero : const Duration(milliseconds: 160),
    curve: Curves.easeOut,
    padding: const EdgeInsets.all(16),
    decoration: BoxDecoration(
      color: selected ? const Color(0xffe8edff) : const Color(0xffffffff),
      border: Border.all(color: selected ? const Color(0xff3153c7) : const Color(0xffb8c0cf)),
      borderRadius: BorderRadius.circular(12),
    ), child: child,
  ));
}
